const items = $input.all();
const results = [];
const seen = new Set();
for (const item of items) {
  if (!item.binary) continue;
  const msgId = item.json.id || item.json.threadId || Math.random().toString(36);
  const rawDate = item.json.internalDate || item.json.date || null;
  let emailDate = new Date().toISOString().slice(0, 10);
  if (rawDate) { const d = new Date(Number(rawDate) > 0 ? Number(rawDate) : rawDate); if (!isNaN(d.getTime())) emailDate = d.toISOString().slice(0, 10); }
  for (const key of Object.keys(item.binary)) {
    const bin = item.binary[key];
    const fileName = (bin.fileName || '').trim();
    if (!fileName) continue;
    const isPdf = (bin.mimeType || '').toLowerCase().includes('pdf') || fileName.toLowerCase().endsWith('.pdf');
    if (!isPdf) continue;
    const dedupKey = msgId + '::' + fileName;
    if (seen.has(dedupKey)) continue;
    seen.add(dedupKey);
    const meta = fileName.match(/(CONTINENTE(?:\s+MODELO)?|GALERIAS|MM\s*BOM\s*DIA|MM|BP|FRANCISCO\s+MANUEL|BOM\s+SUCCESSO)[_ ](\d{8})[._-]?(\d+)_([\d.,]+)\.pdf/i) || fileName.match(/(CONTINENTE|GALERIAS|MM|BP|FRANCISCO\s+MANUEL|BOM\s+SUCCESSO).*?(\d{8})[._-]?(\d+)_([\d.,]+)\.pdf/i);
    let store = null, docDate = null, docNumber = null, docTotal = null;
    if (meta) {
      store = meta[1].toUpperCase().replace(/\s+/g, ' ').trim();
      docDate = meta[2].slice(0,4) + '-' + meta[2].slice(4,6) + '-' + meta[2].slice(6,8);
      docNumber = meta[3];
      docTotal = meta[4];
    }
    results.push({ json: { messageId: msgId, emailDate, fileName, store, docNumber, docDate, docTotal }, binary: { data: bin } });
  }
}
return results;

const TOOLBOX_URL = 'http://toolbox.apps.svc.cluster.local:8000/api/v1/extract/base64';
const FIELD_NAME = 'data';
const allItems = $input.all();
const results = [];
for (let i = 0; i < allItems.length; i++) {
  try {
    const item = allItems[i];
    await this.helpers.assertBinaryData(i, FIELD_NAME);
    const buffer = await this.helpers.getBinaryDataBuffer(i, FIELD_NAME);
    const binary = item.binary ? item.binary[FIELD_NAME] : null;
    const fileName = (binary && binary.fileName) || 'invoice.pdf';
    const mimeType = (binary && binary.mimeType) || 'application/pdf';
    const response = await this.helpers.httpRequest({
      method: 'POST', url: TOOLBOX_URL,
      headers: { 'Content-Type': 'application/json' },
      body: { fileName, mimeType, data: buffer.toString('base64') },
      returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 60000,
    });
    const status = response ? response.statusCode : 0;
    const payload = response ? response.body : null;
    if (status < 200 || status >= 300) throw new Error('Toolbox returned ' + status + ': ' + (typeof payload === 'string' ? payload : JSON.stringify(payload)));
    const text = (payload && typeof payload === 'object') ? (payload.text || payload.markdown || payload.content || JSON.stringify(payload)) : String(payload || '');
    results.push({ json: Object.assign({}, item.json, { text: String(text).substring(0, 60000) }), binary: item.binary });
  } catch (err) {
    results.push({ json: Object.assign({}, allItems[i].json, { text: '', extractError: err.message }), binary: allItems[i].binary, pairedItem: { item: i } });
  }
}
return results;

const items = $input.all();
const L = [ 'Analisa esta fatura de supermercado e retorna APENAS um JSON valido, sem markdown e sem explicacao.', '', 'Schema:', '{', '  "store": string,', '  "document_number": string,', '  "date": "YYYY-MM-DD",', '  "time": "HH:MM" | null,', '  "total": string,', '  "total_net": string | null,', '  "payment_method": string | null,', '  "savings": { "card": string | null, "discounts": string | null },', '  "items": [', '    { "product": string, "quantity": string, "unit": "kg" | "un" | "lt" | null, "unit_price": string, "total": string, "category": string, "brand": string | null }', '  ]', '}', '', 'Regras: TODAS as keys em ingles, exatamente como no schema; valores como string com PONTO decimal (ex: "3.49"); category deve ser UMA de: frutas, vegetais, carne, peixe, laticinios, padaria, mercearia, bebidas, congelados, higiene, limpeza, bebe, animais, outros; nao inventes itens - apenas os que estao na fatura; marca do proprio continente = "Continente".', '' ];
return items.map(item => {
  const j = item.json;
  const p = L.join('\n') + '\nDicas extraidas do nome do ficheiro (usa se o texto nao mostrar): store=' + (j.store || '?') + ', numero=' + (j.docNumber || '?') + ', data=' + (j.docDate || '?') + ', total=' + (j.docTotal || '?') + '\n\nTexto da fatura:\n' + String(j.text || '').substring(0, 12000);
  return { json: Object.assign({}, j, { prompt: p }), binary: item.binary };
});

const llmItems = $input.all();
const src = $('Filtrar PDFs Mercado').all();
const results = [];
function parseNum(s) {
  if (s === null || s === undefined) return null;
  let str = String(s).trim().replace(/[^0-9.,-]/g, '');
  if (!str) return null;
  if (str.includes(',') && str.includes('.')) str = str.replace(/\./g, '').replace(',', '.');
  else if (str.includes(',')) str = str.replace(',', '.');
  const n = parseFloat(str);
  return isNaN(n) ? null : n;
}
const CATS = ['frutas','vegetais','carne','peixe','laticinios','padaria','mercearia','bebidas','congelados','higiene','limpeza','bebe','animais','outros'];
let okCount = 0, errCount = 0, itemCount = 0;
for (let i = 0; i < llmItems.length; i++) {
  const meta = src[i] ? src[i].json : {};
  const bin = src[i] ? src[i].binary : null;
  const raw = llmItems[i].json.llmResponse || (llmItems[i].json.choices && llmItems[i].json.choices[0] && llmItems[i].json.choices[0].message ? llmItems[i].json.choices[0].message.content : '') || '';
  let data = null, parsedOk = false, error = null;
  try {
    let js = raw;
    const cb = raw.match(/```(?:json)?\s*([\s\S]*?)```/);
    if (cb) js = cb[1];
    const jm = js.match(/\{[\s\S]*\}/);
    if (jm) data = JSON.parse(jm[0]);
    if (data && Array.isArray(data.items)) parsedOk = true; else error = 'schema: items em falta';
  } catch (e) { error = 'JSON parse: ' + e.message; }
  if (!data) data = {};
  const loja = data.store || meta.store || 'DESCONHECIDO';
  const numero = String(data.document_number || meta.docNumber || (meta.fileName || '').replace(/\.pdf$/i, ''));
  const data_doc = data.date || meta.docDate || meta.emailDate;
  const total = data.total != null ? String(data.total) : (meta.docTotal || null);
  const itens = (data.items || []).map(it => ({
    product: String(it.product || '').trim(),
    quantity: it.quantity != null ? String(it.quantity) : null,
    unit: it.unit || null,
    unit_price: it.unit_price != null ? String(it.unit_price) : null,
    total: it.total != null ? String(it.total) : null,
    category: CATS.includes(it.category) ? it.category : 'outros',
    brand: it.brand || null,
  }));
  const soma = itens.reduce((acc, it) => acc + (parseNum(it.total) || 0), 0);
  const totalNum = parseNum(total);
  const record = {
    schema: 'mercado_fatura_v2',
    store: loja, document_number: numero, date: data_doc,
    time: data.time || null, total: total, total_net: data.total_net || null,
    payment_method: data.payment_method || null,
    savings: data.savings || { card: null, discounts: null },
    items: itens,
    check: { items_sum: soma.toFixed(2), document_total: totalNum != null ? totalNum.toFixed(2) : null, difference: totalNum != null ? (totalNum - soma).toFixed(2) : null },
    source: { message_id: meta.messageId || null, file: meta.fileName || null, email_received: meta.emailDate || null },
    processed_at: new Date().toISOString(),
  };
  if (parsedOk) okCount++; else errCount++;
  itemCount += itens.length;
  const my = data_doc && data_doc.length >= 7 ? data_doc.slice(5,7) + '-' + data_doc.slice(0,4) : '00-0000';
  const uploadName = my + '_' + loja.replace(/[^A-Za-z0-9]/g, '').slice(0, 20) + '_' + String(numero).replace(/[^A-Za-z0-9]/g, '').slice(0, 25) + '.json';
  results.push({ json: Object.assign({}, meta, { parsedOk: parsedOk, error: error, uploadName: uploadName, record: record }), binary: bin || undefined });
}
const summary = { novas: 0, ok: okCount, erros: errCount, itens: itemCount };
return results.map(r => ({ json: Object.assign({}, r.json, { _summary: summary }) }));

const uploadItems = $input.all();
let existingItems = [];
try { existingItems = $('Listar Ficheiros Mercado').all(); } catch (e) { existingItems = []; }
const existing = new Set(existingItems.map(i => (i.json.name || '').toLowerCase()).filter(n => n));
const novos = uploadItems.filter(i => !existing.has((i.json.uploadName || '').toLowerCase()));
const skipped = uploadItems.length - novos.length;
if (novos.length > 0) novos[0].json._summary.duplicados = skipped;
return novos;

const items = $input.all();
const results = [];
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const jsonStr = JSON.stringify(item.json.record, null, 2);
  const buf = Buffer.from(jsonStr, 'utf8');
  const binaryData = await this.helpers.prepareBinaryData(buf, item.json.uploadName, 'application/json');
  results.push({ json: { uploadName: item.json.uploadName, parsedOk: item.json.parsedOk, _summary: item.json._summary, record: item.json.record }, binary: { data: binaryData } });
}
return results;

const ups = $('Upload JSON').all();
const s = ups.length > 0 && ups[0].json._summary ? ups[0].json._summary : { ok: 0, erros: 0, duplicados: 0, itens: 0 };
let gravados = 0;
try { gravados = $('Gravar no Drive').all().length; } catch (e) { gravados = 0; }
return [{ json: { message: 'Faturas Mercado: ' + (s.ok ?? 0) + ' processadas (' + gravados + ' gravadas), ' + (s.itens ?? 0) + ' itens. Pasta Mercado Dados.' } }];

